/**
 * Public graph barrel: KIND_MODULES + derived views for pull/build/canvas.
 */
import { renderDeferredNamedEntry } from "./deferred-catalog-render.js";
import { KIND_MODULES } from "./modules.js";
import { implementedResourceTypes, isResourceAdoptable, isTfLive, knownResourceTypes, matchType, singleResourceType, } from "./types.js";
export { NO_CANVAS, NO_CATALOG, NO_DATA, NO_LIFECYCLE, defaultMatchResourceType, implementedResourceTypes, isResourceAdoptable, isTfLive, knownResourceTypes, matchType, singleResourceType, } from "./types.js";
export { KIND_MODULES } from "./modules.js";
/** @deprecated Use {@link KIND_MODULES}. */
export const ENTITY_KIND_MODULES = KIND_MODULES;
/** Modules whose data facet participates (not {@link NO_DATA}). */
export const DATA_FACET_MODULES = KIND_MODULES.filter((m) => m.data.participates);
/** Generic direct-reference registry. Resolver engines inspect strategies,
 * never entity/provider names. */
export const REFERENCE_LOOKUP_MODULES = DATA_FACET_MODULES.filter((m) => m.data.participates && (m.data.referenceLookups?.length ?? 0) > 0);
/** Data source type → module (replaces ORG_KIND_BY_TYPE). */
export const DATA_FACET_BY_TYPE = (() => {
    const map = new Map();
    for (const m of DATA_FACET_MODULES) {
        const type = m.data.participates ? m.data.resourceType ?? singleResourceType(m) : undefined;
        if (type !== undefined)
            map.set(type, m);
    }
    return map;
})();
/** Org identity bags written by `edk pull org` (data.orgBag set). */
export const ORG_IDENTITY_BAGS = DATA_FACET_MODULES.filter((m) => m.data.participates && m.data.orgBag !== undefined);
const AI_PROVIDER_KIND_PREFIX = "ai-provider-";
/**
 * `aiProvider({ type })` identifiers → their terraform resource type —
 * one entry per `ai-provider-*` kind, derived from the kind id so authored
 * source never has to name a resource type directly.
 */
export const AI_PROVIDER_RESOURCE_TYPE_BY_TYPE = new Map(ORG_IDENTITY_BAGS.filter((m) => m.kind.startsWith(AI_PROVIDER_KIND_PREFIX)).flatMap((m) => {
    const resourceType = singleResourceType(m);
    return resourceType === undefined ? [] : [[m.kind.slice(AI_PROVIDER_KIND_PREFIX.length), resourceType]];
}));
/** Reverse of {@link AI_PROVIDER_RESOURCE_TYPE_BY_TYPE} — resourceType → public `type`. */
export const AI_PROVIDER_TYPE_BY_RESOURCE_TYPE = new Map([...AI_PROVIDER_RESOURCE_TYPE_BY_TYPE].map(([type, resourceType]) => [resourceType, type]));
/** Backward-compatible metadata view derived from the graph. */
export const RESOURCE_KIND_MODULES = KIND_MODULES.filter(isTfLive).map((m) => ({
    kind: m.kind,
    resourceTypes: implementedResourceTypes(m.resource),
    adoptable: isResourceAdoptable(m.resource),
}));
/** Resource types the §6 adoption gates import. */
export const ADOPTABLE_RESOURCE_TYPES = new Set(KIND_MODULES.filter((m) => isTfLive(m) && isResourceAdoptable(m.resource)).flatMap((m) => implementedResourceTypes(m.resource)));
/** Resource types included in the build-vs-export compare (TF-live ∪ data facets referenced by build). */
export const BUILD_VS_EXPORT_SCOPE_TYPES = new Set([
    ...KIND_MODULES.filter(isTfLive).flatMap((m) => implementedResourceTypes(m.resource)),
    ...DATA_FACET_MODULES.filter((m) => m.data.participates && m.data.referencedByBuild).flatMap((m) => {
        const type = m.data.participates ? m.data.resourceType ?? singleResourceType(m) : undefined;
        return type !== undefined ? [type] : [];
    }),
]);
/** Entity-declared reference aliases normalized by the live round-trip gate. */
export const BUILD_VS_EXPORT_REFERENCE_ALIASES = KIND_MODULES.flatMap((module) => module.roundtrip?.referenceAliases ?? []);
/** Entity-declared typed-data-vs-resolved-literal equivalences for export comparison. */
export const BUILD_VS_EXPORT_RESOLVED_DATA_REFERENCE_EQUIVALENCES = KIND_MODULES.flatMap((module) => (module.roundtrip?.resolvedDataReferences ?? []).flatMap((equivalence) => implementedResourceTypes(module.resource).map((blockType) => ({ blockType, ...equivalence }))));
/** Kind id → module. */
export const KIND_BY_ID = new Map(KIND_MODULES.map((m) => [m.kind, m]));
/** @deprecated Use {@link KIND_BY_ID}. */
export const ENTITY_KIND_BY_ID = KIND_BY_ID;
/**
 * Terraform resource type → owning kind module. Excludes data-facet-only /
 * orgExport kinds so partition does not treat org data types as resources.
 */
export const TYPE_TO_KIND = (() => {
    const map = new Map();
    for (const m of KIND_MODULES) {
        if (m.stream.role === "orgExport" || m.authoring.unit === "none")
            continue;
        for (const type of knownResourceTypes(m.resource)) {
            map.set(type, m);
        }
    }
    return map;
})();
/** Stream-root kinds (app, element, …). */
export const STREAM_ROOT_MODULES = KIND_MODULES.filter((m) => m.stream.role === "streamRoot");
/**
 * Every stream-root kind's own resource type (`elementum_app`,
 * `elementum_element`, …) — lets engine code recognize "this is a stream
 * root" generically, without hardcoding one kind's resource type (see
 * `engine/pull/system-field-state.ts`'s state-backed system-field lookup,
 * which the app path used to own alone before it generalized to cover
 * element-owned system fields too).
 */
export const STREAM_ROOT_RESOURCE_TYPES = new Set(STREAM_ROOT_MODULES.flatMap((m) => knownResourceTypes(m.resource)));
/**
 * Terraform resource type → canonical public authoring type, for every
 * subTyped kind that populates `SubTypeRow.authoringType` (today: field's
 * "USER"/"GROUP"/… discriminant). Lets engine code (e.g.
 * field-refs-registry.ts's `bootstrapFromState`) resolve a resource type to
 * its authoring type generically, without naming the kind or importing
 * entities/ directly.
 */
export const AUTHORING_TYPE_BY_RESOURCE_TYPE = new Map(KIND_MODULES.flatMap((m) => m.resource.shape === "subTypes"
    ? m.resource.rows.flatMap((row) => (row.authoringType === undefined ? [] : [[row.resourceType, row.authoringType]]))
    : []));
/** Own-file children of a parent kind (build discovery + pull print paths). */
export function ownFileChildrenOf(parent) {
    return KIND_MODULES.filter((m) => m.authoring.unit === "ownFile" &&
        m.parents.some((e) => e.parent === parent) &&
        m.lifecycle.participates &&
        m.lifecycle.toTf !== undefined);
}
/**
 * Own-file children that contribute to generated catalogs (may lack `toTf`,
 * e.g. skill / search-table before their TF tranche).
 */
export function ownFileCatalogChildrenOf(parent) {
    return KIND_MODULES.filter((m) => m.authoring.unit === "ownFile" &&
        m.catalog.participates &&
        m.parents.some((e) => e.parent === parent));
}
/** All own-file bags declared under a parent (including stubs without lifecycle). */
export function ownFileBagsUnder(parent) {
    const bags = new Set();
    for (const m of KIND_MODULES) {
        if (m.authoring.unit !== "ownFile")
            continue;
        if (!m.parents.some((e) => e.parent === parent))
            continue;
        bags.add(m.authoring.bag);
    }
    return [...bags].sort();
}
/** Org-root own-file bags (apps, tables, …) — authoring path roots. */
export function orgRootOwnFileBags() {
    return ownFileBagsUnder("org");
}
/** Parent edges for tests / docs. */
export function allParentEdges() {
    return KIND_MODULES.flatMap((m) => m.parents);
}
/** Match a resource type against the graph (false if unknown). */
export function matchResourceType(type) {
    const module = TYPE_TO_KIND.get(type);
    if (module === undefined)
        return undefined;
    const match = matchType(module, type);
    if (match === false)
        return undefined;
    return { module, match };
}
/** Modules whose catalog facet participates. */
export const CATALOG_MODULES = KIND_MODULES.filter((m) => m.catalog.participates);
function catalogMetaOf(facet) {
    return {
        refKind: facet.refKind,
        catalogBag: facet.catalogBag,
        renderOrder: facet.renderOrder,
        catalogRoot: facet.catalogRoot,
        factoryName: facet.factoryName ?? `${facet.refKind}Ref`,
        renderEntry: facet.renderEntry,
    };
}
/**
 * Nested / not-yet-graph-registered catalog bags. Top-level kinds move here
 * off this table onto CatalogFacet as their modules land; nested bags
 * (triggerParameter, tableColumn, …) stay residual.
 */
const DEFERRED_CATALOG_META = [
    {
        refKind: "tableColumn",
        catalogBag: "columns",
        renderOrder: 41,
        catalogRoot: "org",
        factoryName: "tableColumnRef",
        renderEntry: renderDeferredNamedEntry("tableColumnRef"),
    },
    {
        refKind: "documentModelField",
        catalogBag: "fields",
        renderOrder: 56,
        catalogRoot: "app",
        factoryName: "documentModelFieldRef",
        renderEntry: renderDeferredNamedEntry("documentModelFieldRef"),
    },
    {
        refKind: "triggerParameter",
        catalogBag: "trigger",
        renderOrder: 5,
        catalogRoot: "app",
        factoryName: "triggerParameterRef",
        renderEntry: renderDeferredNamedEntry("triggerParameterRef"),
    },
    {
        refKind: "outputProperty",
        catalogBag: "outputs",
        renderOrder: 6,
        catalogRoot: "app",
        factoryName: "outputPropertyRef",
        renderEntry: renderDeferredNamedEntry("outputPropertyRef"),
    },
];
/** refKind → catalog bag / order / root / factory — graph facets win over deferred. */
export const CATALOG_META_BY_REF_KIND = (() => {
    const map = new Map();
    for (const d of DEFERRED_CATALOG_META)
        map.set(d.refKind, d);
    for (const m of CATALOG_MODULES) {
        if (!m.catalog.participates)
            continue;
        map.set(m.catalog.refKind, catalogMetaOf(m.catalog));
    }
    return map;
})();
/** Catalog kinds for a barrel root, ordered by renderOrder. */
export function catalogKindsForRoot(root) {
    const want = root === "org" ? "org" : "app";
    return [...CATALOG_META_BY_REF_KIND.values()]
        .filter((m) => m.catalogRoot === want)
        .sort((a, b) => a.renderOrder - b.renderOrder || a.refKind.localeCompare(b.refKind));
}
/** Bag property name for a CatalogRef.__kind, or undefined if unknown. */
export function catalogBagForRefKind(refKind) {
    return CATALOG_META_BY_REF_KIND.get(refKind)?.catalogBag;
}
